const paymentFilters={search:'',company:'',status:'',provider:'',source:'',from:'',to:''};
let paymentPage=1;
let paymentPageSize=5;
const paymentAmount=value=>Number(value).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2})+' BDT';
const paymentStatusLabel=status=>status.replaceAll('_',' ');
const paymentStatusPill=status=>`<span class="pm-status pm-${status}">${paymentStatusLabel(status)}</span>`;
function paymentHeader(title,description,actions=''){return `<header class="pm-hero"><div><span class="eyebrow">PAYMENT MANAGEMENT</span><h1>${title}</h1><p>${description}</p></div><div class="pm-hero-actions">${actions}</div></header>`;}
function paymentCard(title,subtitle,body,link=''){return `<section class="pm-card"><div class="pm-card-head"><div><h2>${title}</h2><p>${subtitle}</p></div>${link}</div>${body}</section>`;}
function paymentTable(headers,body,empty){return body?`<div class="pm-table-wrap"><table class="pm-table"><thead><tr>${headers.map(label=>`<th>${label}</th>`).join('')}</tr></thead><tbody>${body}</tbody></table></div>`:`<div class="pm-empty">${empty}</div>`;}
const sharedPagination=(...args)=>window.suitePagination(...args);
function renderPaymentOverview(){
  const settled=paymentRows.filter(row=>row.status==='settled'),gross=settled.reduce((sum,row)=>sum+row.amount,0),net=gross-paymentRows.filter(row=>row.status==='refunded').reduce((sum,row)=>sum+row.amount,0),needs=paymentRows.filter(row=>['failed','reconciliation_required'].includes(row.status)).length;
  const stats=[['Gross settled',paymentAmount(gross),'Successful checkouts'],['Net collected',paymentAmount(net),'After completed refunds'],['Settled payments',settled.length,`Of ${paymentRows.length} checkout attempts`],['Needs attention',needs,'Reconciliation or failed activity']];
  const providerRows=['sslcommerz','bkash'].map(provider=>{const rows=paymentRows.filter(row=>row.provider===provider),paid=rows.filter(row=>row.status==='settled');return `<tr><td><strong>${provider==='sslcommerz'?'SSLCommerz':'bKash'}</strong></td><td>${rows.length}</td><td>${paid.length}</td><td>${rows.filter(row=>row.status==='failed').length}</td><td>${paymentAmount(paid.reduce((sum,row)=>sum+row.amount,0))}</td><td>${paymentAmount(rows.filter(row=>row.status==='refunded').reduce((sum,row)=>sum+row.amount,0))}</td></tr>`}).join('');
  const exceptions=paymentRows.filter(row=>['failed','refund_pending','reconciliation_required'].includes(row.status));const exceptionBody=exceptions.map(row=>`<tr><td>${row.date}</td><td><strong>${esc(row.customer)}</strong><small>${esc(row.item)}</small></td><td>${row.provider==='bkash'?'bKash':'SSLCommerz'}</td><td><button class="pm-id" data-pm-detail="${row.id}">${row.id}</button></td><td>${paymentAmount(row.amount)}</td><td>${paymentStatusPill(row.status)}</td></tr>`).join('');
  const counts=[['Pending checkouts',1,'session_created'],['Refunds in progress',1,'refund_pending'],['Reconciliation required',1,'reconciliation_required'],['Failed or cancelled',1,'failed']];
  return `<div class="payment-mock">${paymentHeader('Payment overview','Monitor checkout performance, settlement value, refunds, and exceptions across your configured providers.',`<a class="btn" href="#/app/payment-management/transactions">Open transactions</a><a class="btn" href="#/app/payment-management/reconciliation">Reconciliation</a><a class="btn primary" href="#/app/payment-management/methods">Payment accounts</a>`)}<div class="pm-overview-filters"><label>Company<select data-pm-filter="company"><option value="">All companies</option><option value="Stravix Group BD">Stravix Group BD</option></select></label><label>From<input type="date" data-pm-filter="from" value="2026-09-01"></label><label>To<input type="date" data-pm-filter="to" value="2026-09-25"></label><button class="btn primary" data-pm-apply>Apply filters</button></div><div class="pm-period">Showing 1 Sep 2026 – 25 Sep 2026 · All companies</div><div class="pm-stats">${stats.map(([label,value,note])=>`<article><span>${label}</span><strong>${value}</strong><small>${note}</small></article>`).join('')}</div><div class="pm-overview-grid">${paymentCard('Provider performance','Compare settlement and refund activity by gateway.',paymentTable(['Provider','Checkouts','Settled','Failed','Gross settled','Refunded'],providerRows,'No provider activity in this period.'))}${paymentCard('Provider readiness','Configuration and credential readiness for company checkout accounts.',`<div class="pm-provider-list"><div><span class="pm-provider-icon">S</span><span><strong>SSLCommerz</strong><small>1 configured · 1 enabled</small></span><b>Ready</b></div><div><span class="pm-provider-icon">b</span><span><strong>bKash</strong><small>1 configured · 1 enabled</small></span><b>Ready</b></div><div><span class="pm-provider-icon">N</span><span><strong>Nagad</strong><small>0 configured · 0 enabled</small></span><b class="muted">Not configured</b></div></div>`)}${paymentCard('Operational counts','Use the transaction workspace for the complete audit trail.',`<div class="pm-count-list">${counts.map(([label,value,status])=>`<a href="#/app/payment-management/transactions?status=${status}"><span>${label}</span><strong>${value} ↗</strong></a>`).join('')}</div>`)}</div>${paymentCard('Recent exceptions','The latest failed, pending refund, and reconciliation-required operations.',paymentTable(['Date','Learner / course','Provider','Transaction','Amount','Status'],exceptionBody,'No payment exceptions in this period.'),`<a href="#/app/payment-management/transactions">View all transactions ↗</a>`)}</div>`;
}
function paymentTransactionVisible(reconciliation){const params=new URLSearchParams(location.hash.split('?')[1]||'');const status=paymentFilters.status||params.get('status')||(reconciliation?'reconciliation_required':'');return paymentRows.filter(row=>(!paymentFilters.search||`${row.customer} ${row.email} ${row.item} ${row.order} ${row.id}`.toLowerCase().includes(paymentFilters.search.toLowerCase()))&&(!status||row.status===status)&&(!paymentFilters.provider||row.provider===paymentFilters.provider)&&(!paymentFilters.source||row.source.toLowerCase().includes(paymentFilters.source.toLowerCase())));}
function renderPaymentTransactions(path){const routeParams=new URLSearchParams(location.hash.split('?')[1]||'');if(routeParams.has('search')&&!paymentFilters.search)paymentFilters.search=routeParams.get('search')||'';const reconciliation=path.endsWith('/reconciliation'),rows=paymentTransactionVisible(reconciliation),status=routeParams.get('status')||paymentFilters.status||(reconciliation?'reconciliation_required':''),pageCount=Math.max(1,Math.ceil(rows.length/paymentPageSize));paymentPage=Math.min(paymentPage,pageCount);const visibleRows=rows.slice((paymentPage-1)*paymentPageSize,paymentPage*paymentPageSize);const statusOptions=['created','session_created','settled','failed','cancelled','expired','validation_failed','reconciliation_required','refund_pending','refunded'];const input=(key,label,placeholder)=>`<label><span>${label}</span><input data-pm-filter="${key}" value="${esc(paymentFilters[key])}" placeholder="${placeholder}"></label>`;const select=(key,label,values,all,current)=>`<label><span>${label}</span><select data-pm-filter="${key}"><option value="">${all}</option>${values.map(value=>`<option value="${value}" ${current===value?'selected':''}>${paymentStatusLabel(value)}</option>`).join('')}</select></label>`;const body=visibleRows.map(row=>`<tr><td>${row.date}</td><td><strong>${esc(row.customer)}</strong><small>${esc(row.email)}</small></td><td><strong>${esc(row.item)}</strong><small>${row.order}</small></td><td>${row.provider==='bkash'?'bKash':'SSLCommerz'}</td><td><button class="pm-id" data-pm-detail="${row.id}">${row.id}</button><small>GW-${row.id.slice(4)}</small></td><td>${paymentAmount(row.amount)}</td><td>${paymentStatusPill(row.status)}</td><td>${row.company}</td><td><button class="pm-action" data-pm-detail="${row.id}">Details ↗</button></td></tr>`).join('');return `<div class="payment-mock">${paymentHeader(reconciliation?'Reconciliation workspace':'Transaction history',reconciliation?'Review operations that need provider confirmation and refresh their status from the gateway.':'Search and review gateway checkout, settlement, and refund activity across payment providers.',`<span class="pm-count-chip">${rows.length} transactions</span><button class="btn" data-pm-export>Export current page</button>`)}<section class="pm-card"><div class="pm-list-filters">${input('search','Search','Customer, item, order, or transaction')}${select('company','Company',['Stravix Group BD'],'All companies',paymentFilters.company)}${select('status','Status',statusOptions,'All statuses',status)}${select('provider','Provider',['sslcommerz','bkash'],'All providers',paymentFilters.provider)}${input('source','Source','Any source module')}<label><span>From</span><input data-pm-filter="from" type="date" value="${paymentFilters.from}"></label><label><span>To</span><input data-pm-filter="to" type="date" value="${paymentFilters.to}"></label><button class="btn primary" data-pm-apply>Apply filters</button><button class="btn" data-pm-reset>Reset</button></div>${paymentTable(['Date','Customer','Item','Provider','Transaction','Amount','Status','Company','Action'],body,'No payment transactions match the current filters.')}${sharedPagination(rows.length,paymentPage,paymentPageSize,'transactions')}</section></div>`;}
function paymentDetailDrawer(row){return `<div class="pm-detail-drawer"><div class="pm-drawer-hero"><span class="eyebrow">PAYMENT DETAILS</span><h3>${row.id}</h3><p>${row.customer} · ${row.item}</p>${paymentStatusPill(row.status)}</div><div class="pm-detail-grid">${[['Customer',row.customer],['Item',row.item],['Item type',row.source==='Training'?'Course':'Product'],['Order',row.order],['Merchant transaction',row.id],['Merchant account',row.provider==='bkash'?'bKash · Primary':'SSLCommerz · Primary'],['Provider transaction','GW-'+row.id.slice(4)],['Amount',paymentAmount(row.amount)]].map(([label,value])=>`<div><span>${label}</span><strong>${esc(value)}</strong></div>`).join('')}</div><h4>Payment timeline</h4><div class="pm-timeline"><span>${row.date}</span><strong>${row.type==='refund'?'Refund':'Checkout'}</strong>${paymentStatusPill(row.status)}<span>${paymentAmount(row.amount)}</span></div>${row.status==='reconciliation_required'?'<h4>Reconciliation</h4><div class="pm-timeline"><span>Yesterday</span><strong>Provider comparison</strong><span>Review required</span></div>':''}${row.type==='refund'?'<h4>Refunds</h4><div class="pm-timeline"><span>Requested</span><strong>Customer request</strong><span>Provider confirmation pending</span></div>':''}<h4>Event history</h4><div class="pm-timeline"><span>${row.date}</span><strong>${row.type}</strong><span>Created → ${paymentStatusLabel(row.status)}</span></div><div class="pm-drawer-actions"><button class="btn" data-pm-receipt>Show receipt</button>${row.status==='settled'?'<button class="btn" data-pm-refund>Refund payment</button>':''}${row.status==='reconciliation_required'?'<button class="btn primary" data-pm-reconcile>Open manual reconciliation</button>':''}</div></div>`;}
root.addEventListener('input',event=>{const key=event.target.dataset.pmFilter;if(!key)return;paymentFilters[key]=event.target.value;if(key==='search'){paymentPage=1;render(true);}});
root.addEventListener('change',event=>{if(event.target.matches('[data-suite-page-size]')){paymentPageSize=Number(event.target.value)||5;paymentPage=1;render();return;}const key=event.target.dataset.pmFilter;if(!key)return;paymentFilters[key]=event.target.value;paymentPage=1;});
root.addEventListener('click',event=>{const pageButton=event.target.closest('[data-suite-page]');if(pageButton&&!pageButton.disabled){paymentPage=Number(pageButton.dataset.suitePage)||1;render();return;}if(event.target.closest('[data-pm-reset]')){for(const key of Object.keys(paymentFilters))paymentFilters[key]='';paymentPage=1;paymentPageSize=5;location.hash='#/app/payment-management/transactions';render();return;}if(event.target.closest('[data-pm-apply]')){paymentPage=1;render();return;}if(event.target.closest('[data-pm-export]')){flash('Sample export prepared for design review.');return;}const id=event.target.closest('[data-pm-detail]')?.dataset.pmDetail;if(id){const row=paymentRows.find(item=>item.id===id);if(!row)return;activeAction='Payment details';activeOverlayClass='pm-detail-overlay';activeOverlayHTML=paymentDetailDrawer(row);drawer='original';render();return;}if(event.target.closest('[data-pm-receipt]')){flash('Sample receipt PAY-RCPT-2048 · Issued 25 Sep 2026.');return;}if(event.target.closest('[data-pm-refund]')){activeAction='Refund payment';activeOverlayHTML='<div class="pm-refund-form"><p>Submit a full or partial refund through the configured payment provider.</p><label>Refund amount<input type="number" value="125.40"></label><label>Reason<textarea placeholder="Why is this payment being refunded?"></textarea></label><button class="btn primary" data-pm-refund-save>Preview refund request</button></div>';drawer='original';render();return;}if(event.target.closest('[data-pm-refund-save]')){drawer='';flash('Sample refund request recorded.');return;}if(event.target.closest('[data-pm-reconcile]')){drawer='';location.hash='#/app/payment-management/reconciliation/review';return;}});

