function renderPaymentMethods(){return `<div class="payment-mock">${paymentHeader('Company payment accounts','Configure the company merchant accounts that process learner checkout.',`<span class="pm-method-company">Company · Stravix Group BD</span><span class="pm-count-chip">Configured ${paymentAccounts.length}</span><button class="btn" data-pm-refresh>Refresh</button><button class="btn primary" data-pm-account="new">Add payment account</button>`)}<div class="pm-info-banner"><strong>Merchant accounts are company-specific</strong><p>Configure each company’s bKash, Nagad, Rocket, SSLCommerz, or Stripe credentials here. Secrets remain protected and are never shown after saving.</p></div>${paymentCard('Configured accounts','These settings determine how learner checkout works for the selected company.',`<div class="pm-accounts">${paymentAccounts.map(account=>`<article class="pm-account ${account.enabled?'':'disabled'}"><span class="pm-account-icon">${account.method==='SSLCommerz'?'S':account.method==='bKash'?'b':'N'}</span><div class="pm-account-content"><div class="pm-account-head"><div><h3>${account.method}</h3><p>${account.provider}</p></div><span class="pm-account-status ${account.enabled?'enabled':'disabled'}">${account.enabled?'Enabled':'Disabled'}</span>${account.default?'<span class="pm-default">Default</span>':''}</div><dl><div><dt>Environment</dt><dd>${account.environment}</dd></div><div><dt>Configuration</dt><dd>${account.configured}</dd></div></dl></div><button class="btn" data-pm-account="${account.id}">Edit</button></article>`).join('')}</div>`,`<span class="pm-count-chip subtle">${paymentAccounts.length} total</span>`)}</div>`;}
function paymentAccountDrawer(account){const editing=Boolean(account);return `<div class="pm-account-drawer"><div class="pm-drawer-section"><div class="pm-step"><span>1</span><div><h3>Account settings</h3><p>Choose the provider and whether this account can be used at checkout.</p></div></div><div class="pm-account-fields"><label>Payment method *<select data-pm-account-field="method">${['SSLCommerz','bKash','Nagad','Rocket','Stripe'].map(method=>`<option ${account?.method===method?'selected':''}>${method}</option>`).join('')}</select></label><label>Status<select data-pm-account-field="status"><option ${account?.enabled!==false?'selected':''}>Enabled</option><option ${account?.enabled===false?'selected':''}>Disabled</option></select></label><label>Default account<select data-pm-account-field="default"><option ${account?.default?'selected':''}>Use as default</option><option ${!account?.default?'selected':''}>Keep as backup</option></select></label></div></div><div class="pm-drawer-section"><div class="pm-step"><span>2</span><div><h3>${account?.method||'SSLCommerz'} checkout</h3><p>Connect this company’s merchant account for automated learner checkout.</p></div></div><div class="pm-account-fields"><label>Environment *<select><option>Live</option><option>Sandbox</option></select></label><label>Store ID<input placeholder="Merchant store ID"></label><label>Store password secret reference<input placeholder="Configuration or secret-provider key"></label></div><p class="pm-safe-note">This is a visual mock. Entered values stay in this browser preview.</p></div><div class="pm-drawer-section"><div class="pm-step"><span>3</span><div><h3>Connection settings</h3><p>Add only the configuration values required by this payment method.</p></div></div><div class="pm-account-fields"><label>Setting name<input placeholder="Setting name"></label><label>Value<input placeholder="Value"></label></div><button class="btn" data-pm-add-setting>Add setting</button></div><div class="pm-drawer-actions"><button class="btn primary" data-pm-account-save>${editing?'Save changes':'Add payment account'}</button><button class="btn" data-action="close">Cancel</button></div></div>`;}

