function refundDecisionDrawer(kind,row){return `<div class="pm-work-drawer"><p>${kind==='approve'?'Approve this refund request and submit it to the payment provider.':'Reject this refund request with a reason recorded for audit.'}</p><div class="pm-detail-grid">${[['Customer',row.customer],['Email',row.email],['Item',row.item],['Order',row.order],['Provider',paymentProviderName(row.provider)],['Amount',paymentAmount(row.amount)],['Reason',row.reason]].map(([label,value])=>`<div><span>${label}</span><strong>${esc(value)}</strong></div>`).join('')}</div><label>Decision notes<textarea rows="5" placeholder="Record your decision and supporting context"></textarea></label><div class="pm-drawer-actions"><button class="btn primary" data-pm-work-save="refund">${kind==='approve'?'Approve and submit refund':'Reject request'}</button><button class="btn" data-action="close">Cancel</button></div></div>`;}

