root.addEventListener('click',event=>{if(event.target.closest('[data-pm-work-reset]')){for(const key of Object.keys(paymentWorkFilters))paymentWorkFilters[key]='';render();return;}if(event.target.closest('[data-pm-work-apply]')){render();return;}const decision=event.target.closest('[data-pm-refund-decision]')?.dataset.pmRefundDecision;if(decision){const [kind,id]=decision.split('|'),row=refundApprovals.find(item=>item.id===id);activeAction=kind==='approve'?'Approve refund':'Reject refund';activeOverlayHTML=refundDecisionDrawer(kind,row);activeOverlayClass='pm-work-overlay';drawer='original';render();return;}if(event.target.closest('[data-pm-link-create]')){activeAction='Create payment link';activeOverlayHTML=paymentLinkDrawer();activeOverlayClass='pm-work-overlay';drawer='original';render();return;}if(event.target.closest('[data-pm-link-revoke]')){flash('Sample payment link revoked for design review.');return;}const settlementId=event.target.closest('[data-pm-settlement]')?.dataset.pmSettlement;if(settlementId){activeAction='Settlement summary';activeOverlayHTML=settlementDetailDrawer(paymentSettlements.find(row=>row.id===settlementId));activeOverlayClass='pm-work-overlay';drawer='original';render();return;}if(event.target.closest('[data-pm-settlement-import]')){activeAction='Import settlement';activeOverlayHTML=settlementImportDrawer();activeOverlayClass='pm-work-overlay';drawer='original';render();return;}if(event.target.closest('[data-pm-close-on-nav]')){drawer='';return;}const saved=event.target.closest('[data-pm-work-save]')?.dataset.pmWorkSave;if(saved){drawer='';flash(`Sample ${saved} action recorded in this design preview.`);render();return;}});
